for i, (name, lang, prompt, check) in enumerate(fix_prompts):
    ext = {"python": "py", "javascript": "js", "typescript": "ts", "rust": "rs", "go": "go", "cpp": "cpp", "java": "java"}.get(lang, "txt")
    EXERCISES.append({"id": f"fix-{name:20s}", "lang": lang, "prompt": prompt, "check_str": check, "check_file": f"solution.{ext}"})

print(f"Total exercises: {len(EXERCISES)}")
